package com.arjunren.leave.entity;
import jakarta.persistence.*; import java.time.Instant;
@Entity@Table(name="employee_profiles",indexes={@Index(name="employees_manager_idx",columnList="manager_id"),@Index(name="employees_department_idx",columnList="department")})public class EmployeeProfile{@Id@GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@Column(name="employee_number",nullable=false,unique=true,length=30)private String employeeNumber;@OneToOne(optional=false,fetch=FetchType.LAZY)@JoinColumn(name="user_id",unique=true)private AppUser user;@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="manager_id")private AppUser manager;@Column(nullable=false,length=120)private String department;@Column(name="annual_balance",nullable=false)private int annualBalance=20;@Column(name="sick_balance",nullable=false)private int sickBalance=10;@Column(name="created_at",nullable=false,updatable=false)private Instant createdAt=Instant.now();@Column(name="updated_at",nullable=false)private Instant updatedAt=Instant.now();protected EmployeeProfile(){}public EmployeeProfile(String n,AppUser u,AppUser m,String d,int a,int s){employeeNumber=n;user=u;manager=m;department=d;annualBalance=a;sickBalance=s;}@PreUpdate void ts(){updatedAt=Instant.now();}public void useAnnual(int d){annualBalance-=d;}public void useSick(int d){sickBalance-=d;}public Long getId(){return id;}public String getEmployeeNumber(){return employeeNumber;}public AppUser getUser(){return user;}public AppUser getManager(){return manager;}public String getDepartment(){return department;}public int getAnnualBalance(){return annualBalance;}public int getSickBalance(){return sickBalance;}public Instant getCreatedAt(){return createdAt;}}

